// §14.6 Bot de Telegram: la pregunta va a Spring y la respuesta vuelve con citas.
//
// El flujo solo transporta (§14). El embedding de la pregunta, el filtro de
// audiencia, el umbral y los guardrails del prompt viven en Spring; n8n no
// habla con el LLM ni con Qdrant.
//
// El rol se fija AQUI y no lo elige quien escribe, porque el rol es lo que
// decide que documentos se pueden recuperar. Por defecto RESIDENTE, que es el
// mas restrictivo: asi un chat de Telegram no sirve para sacar los protocolos
// de vigilancia (§11). Subirlo a VIGILANTE solo tiene sentido con un bot
// privado cuyo chat controles.

const mensaje = $json.message || {};
const chatId = mensaje.chat && mensaje.chat.id;
const texto = String(mensaje.text || '').trim();

if (!chatId) {
  throw new Error('Mensaje de Telegram sin chat id');
}

// Un comando (/start, /help) no es una pregunta: si se mandara al asistente
// caeria bajo el umbral, emitiria RAG_SIN_RESPUESTA y ensuciaria el panel de
// preguntas sin respuesta, que es justo la lista de huecos del reglamento.
// Sin items, los nodos siguientes no se ejecutan.
if (!texto || texto.startsWith('/')) {
  console.log('Mensaje ignorado (vacio o comando): ' + texto);
  return [];
}

return [{
  json: {
    chatId,
    rol: $env.TELEGRAM_ROL || 'RESIDENTE',
    // El actor alimenta el limite de frecuencia por actor de §16.
    actor: 'telegram:' + chatId,
    pregunta: texto.slice(0, 1000),
  },
}];

// Da forma a la respuesta de Spring para un chat de texto.
//
// Las fuentes se muestran siempre que vengan: una respuesta del asistente sin
// la cita de donde sale no vale para un reglamento (§11).

const r = $json || {};
const chatId = $('Preparar la pregunta').item.json.chatId;
const lineas = [r.texto || 'El asistente no devolvio texto.'];

if (Array.isArray(r.fuentes) && r.fuentes.length > 0) {
  lineas.push('', 'Fuentes: ' + r.fuentes.join(' | '));
}

if (r.sinRespuesta) {
  lineas.push('', 'Esto no esta en los documentos del conjunto. Queda anotado para que la administracion lo documente.');
}

if (r.disponible === false) {
  lineas.push('', 'Lo que falla es solo el asistente: la porteria funciona con normalidad.');
}

return [{ json: { chatId, respuesta: lineas.join('\n') } }];
